/**
 * Gibt alle Krankenhäuser für eine Stadt zurück (case-insensitive)
 * @param {string} city
 * @returns {Hospital[]}
 */
export function getHospitalsByCity(city) {
  const q = city.toLowerCase().trim()
  return DE_HOSPITALS.filter(h => h.city.toLowerCase() === q)
}

/**
 * Sucht Krankenhäuser nach Name-Präfix (für Autocomplete)
 * @param {string} query
 * @param {string} [city]
 * @returns {Hospital[]}
 */
export function searchHospitals(query, city) {
  const q = query.toLowerCase().trim()
  let list = city ? getHospitalsByCity(city) : DE_HOSPITALS
  return list.filter(h => h.name.toLowerCase().includes(q)).slice(0, 20)
}
